const DAYS=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
let S={tasks:[],sessions:[],rules:[],exam:[]};
let REV={};
let TODAY='';
let examDate='';
const $=id=>document.getElementById(id);
function parse(s){const p=s.split('-').map(Number);return Date.UTC(p[0],p[1]-1,p[2]);}
function fmt(ms){return new Date(ms).toISOString().slice(0,10);}
function addDays(s,n){return fmt(parse(s)+n*86400000);}
function wd(s){return new Date(parse(s)).getUTCDay();}
function pretty(s){return new Date(parse(s)).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});}
function say(t,bad){const e=$('status');e.textContent=t;e.className='status'+(bad?' bad':'');}
function rev(c,id){const m=REV[c];return m&&m[id]?m[id]:1;}
function windowDays(){
  let last=addDays(examDate,-1);
  if(last<TODAY)last=TODAY;
  const out=[];
  for(let d=TODAY;d<=last&&out.length<400;d=addDays(d,1))out.push(d);
  return out;
}
function blockedSet(extra){
  const b=new Set(S.rules.map(r=>r.weekday));
  if(extra!==undefined)b.add(extra);
  return b;
}
function loadMap(){
  const m=new Map();
  for(const s of S.sessions){m.set(s.date,(m.get(s.date)||0)+1);}
  return m;
}
async function load(){
  const r=await tessera.call('data.read',{});
  const d=r.data||{};
  S={tasks:d.tasks||[],sessions:d.sessions||[],rules:d.rules||[],exam:d.exam||[]};
  REV=r.revisions||{};
  examDate=S.exam.length?S.exam[0].date:addDays(TODAY,14);
  render();
}
function render(){
  $('exam-date').value=examDate;
  const rl=$('rules');rl.textContent='';
  const rs=S.rules.slice().sort((a,b)=>a.weekday-b.weekday);
  if(!rs.length){const li=document.createElement('li');li.textContent='Nenhum dia bloqueado.';rl.appendChild(li);}
  for(const r of rs){
    const li=document.createElement('li');li.setAttribute('data-hook','rule');
    const sp=document.createElement('span');sp.textContent='Nunca estudo: '+DAYS[r.weekday];
    const b=document.createElement('button');b.type='button';b.className='secondary';b.setAttribute('data-hook','rule-remove');b.textContent='Remover';
    b.setAttribute('aria-label','Remover bloqueio de '+DAYS[r.weekday]);
    b.addEventListener('click',()=>removeRule(r.id));
    li.appendChild(sp);li.appendChild(b);rl.appendChild(li);
  }
  const names=new Map();for(const t of S.tasks)names.set(t.id,t.name);
  const ss=S.sessions.filter(s=>names.has(s.taskId)).sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);
  $('empty').style.display=ss.length?'none':'';
  const sl=$('sessions');sl.textContent='';
  for(const s of ss){
    const li=document.createElement('li');li.setAttribute('data-hook','session');
    if(s.done)li.className='done';
    const info=document.createElement('span');info.className='info';
    const tm=document.createElement('time');tm.setAttribute('datetime',s.date);tm.textContent=pretty(s.date)+' (à noite)';
    const tn=document.createElement('strong');tn.className='tname';tn.setAttribute('data-hook','session-task');tn.textContent=names.get(s.taskId);
    info.appendChild(tm);info.appendChild(tn);
    const lab=document.createElement('label');lab.className='chk';
    const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!s.done;
    cb.addEventListener('change',()=>toggleDone(s.id,cb.checked));
    lab.appendChild(cb);lab.appendChild(document.createTextNode('Estudado'));
    li.appendChild(info);li.appendChild(lab);sl.appendChild(li);
  }
  const tl=$('tasks');tl.textContent='';
  for(const t of S.tasks){
    const li=document.createElement('li');
    const sp=document.createElement('span');sp.textContent=t.name;
    const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent='Excluir';
    b.setAttribute('aria-label','Excluir o assunto '+t.name+' e suas sessões');
    b.addEventListener('click',()=>removeTask(t.id));
    li.appendChild(sp);li.appendChild(b);tl.appendChild(li);
  }
}
async function patch(ops){return tessera.call('data.patch',{operations:ops});}
async function addTask(){
  const inp=$('task-name');const name=inp.value.trim();
  const err=$('task-error');err.textContent='';
  if(!name){err.textContent='Digite o nome do assunto.';inp.focus();return;}
  const blocked=blockedSet();
  const days=windowDays().filter(d=>!blocked.has(wd(d)));
  if(!days.length){err.textContent='Não há dias livres antes da prova. Mude a data da prova ou remova um bloqueio.';return;}
  const lm=loadMap();
  const chosen=[];
  const want=Math.min(2,days.length);
  for(let i=0;i<want;i++){
    let best=null,bs=null;
    for(const d of days){
      if(chosen.indexOf(d)>=0)continue;
      let near=0;
      for(const c of chosen){if(Math.abs(parse(c)-parse(d))<3*86400000)near=1;}
      const sc=[near,lm.get(d)||0,d];
      if(bs===null||sc[0]<bs[0]||(sc[0]===bs[0]&&(sc[1]<bs[1]||(sc[1]===bs[1]&&sc[2]<bs[2])))){bs=sc;best=d;}
    }
    if(best===null)break;
    chosen.push(best);lm.set(best,(lm.get(best)||0)+1);
  }
  try{
    const res=await patch([{op:'add',collection:'tasks',record:{name:name}}]);
    const id=res.addedIds[0];
    const ops=chosen.map(d=>({op:'add',collection:'sessions',record:{taskId:id,date:d,done:false}}));
    await patch(ops);
    inp.value='';
    say('Assunto adicionado com '+chosen.length+' sessão(ões).');
    await load();
  }catch(e){say('Não foi possível adicionar o assunto. Tente de novo.',true);}
}
async function addRule(){
  const w=Number($('rule-day').value);
  const err=$('rule-error');err.textContent='';
  if(S.rules.some(r=>r.weekday===w)){err.textContent=DAYS[w]+' já está bloqueado.';return;}
  const blocked=blockedSet(w);
  if(blocked.size>=7){err.textContent='Não dá para bloquear todos os dias da semana.';return;}
  const days=windowDays().filter(d=>!blocked.has(wd(d)));
  const moving=S.sessions.filter(s=>s.date>=TODAY&&wd(s.date)===w);
  if(moving.length&&!days.length){err.textContent='Não restariam dias livres antes da prova. Mude a data da prova.';return;}
  const lm=loadMap();
  const ops=[{op:'add',collection:'rules',record:{weekday:w}}];
  for(const s of moving){
    lm.set(s.date,(lm.get(s.date)||1)-1);
    let best=null,bs=null;
    for(const d of days){
      const same=S.sessions.some(o=>o.taskId===s.taskId&&o.id!==s.id&&o.date===d)?1:0;
      const dist=Math.abs(parse(d)-parse(s.date));
      const sc=[same,lm.get(d)||0,dist];
      if(bs===null||sc[0]<bs[0]||(sc[0]===bs[0]&&(sc[1]<bs[1]||(sc[1]===bs[1]&&sc[2]<bs[2])))){bs=sc;best=d;}
    }
    lm.set(best,(lm.get(best)||0)+1);
    ops.push({op:'replace',collection:'sessions',id:s.id,revisionCount:rev('sessions',s.id),fields:{date:best}});
  }
  try{
    await patch(ops);
    say(DAYS[w]+' bloqueado. '+moving.length+' sessão(ões) mudaram de dia.');
    await load();
  }catch(e){say('Não foi possível bloquear o dia. Tente de novo.',true);}
}
async function removeRule(id){
  try{
    await patch([{op:'remove',collection:'rules',id:id,revisionCount:rev('rules',id)}]);
    say('Bloqueio removido. As sessões atuais continuam onde estão.');
    await load();
  }catch(e){say('Não foi possível remover o bloqueio.',true);}
}
async function removeTask(id){
  const ops=S.sessions.filter(s=>s.taskId===id).map(s=>({op:'remove',collection:'sessions',id:s.id,revisionCount:rev('sessions',s.id)}));
  ops.push({op:'remove',collection:'tasks',id:id,revisionCount:rev('tasks',id)});
  try{await patch(ops);say('Assunto excluído com suas sessões.');await load();}
  catch(e){say('Não foi possível excluir o assunto.',true);}
}
async function toggleDone(id,v){
  try{await patch([{op:'replace',collection:'sessions',id:id,revisionCount:rev('sessions',id),fields:{done:v}}]);await load();}
  catch(e){say('Não foi possível marcar a sessão.',true);await load();}
}
async function setExam(){
  const v=$('exam-date').value;
  if(!v){say('Escolha uma data válida para a prova.',true);return;}
  try{
    if(S.exam.length)await patch([{op:'replace',collection:'exam',id:S.exam[0].id,revisionCount:rev('exam',S.exam[0].id),fields:{date:v}}]);
    else await patch([{op:'add',collection:'exam',record:{date:v}}]);
    say('Data da prova salva. Os próximos assuntos usarão essa data.');
    await load();
  }catch(e){say('Não foi possível salvar a data.',true);}
}
$('task-add').addEventListener('click',addTask);
$('task-name').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addTask();}});
$('rule-add').addEventListener('click',addRule);
$('exam-date').addEventListener('change',setExam);
(async function(){
  try{
    const c=await tessera.call('clock.now',{});
    TODAY=c.date;
    await load();
  }catch(e){say('Não foi possível carregar o plano.',true);}
})();

