  try{await patch(ops);say('Assunto excluído com suas sessões.');await load();}
  catch(e){say('Não foi possível excluir o assunto.',true);}
}
async function toggleDone(id,v){
  try{await patch([{op:'replace',collection:'sessions',id:id,revisionCount:rev('sessions',id),fields:{done:v}}]);await load();}
  catch(e){say('Não foi possível marcar a sessão.',true);await load();}
}
async function setExam(){
  const v=$('exam-date').value;
  if(!v){say('Escolha uma data válida para a prova.',true);return;}
  try{
    if(S.exam.length)await patch([{op:'replace',collection:'exam',id:S.exam[0].id,revisionCount:rev('exam',S.exam[0].id),fields:{date:v}}]);
    else await patch([{op:'add',collection:'exam',record:{date:v}}]);
    say('Data da prova salva. Os próximos assuntos usarão essa data.');
    await load();
  }catch(e){say('Não foi possível salvar a data.',true);}
}
